!function(){"use strict";var n=window.PF;n&&!n.skip("war-report")&&n.holder().insertAdjacentHTML("beforeend",'<template id="pf-ov-warreport">\n<div class="fe-block pf-override-block" id="pf-warreport">\n<h2>&#9876; War Report</h2>\n<div class="c-tag">The week that was, straight from Command. Email\'s down — the report lives here.</div>\n<div id="xWarReport"><div class="c-load">Requesting the report&hellip;</div></div>\n</div>\n<script>\n(function(){\nvar BACKEND=window.PF_BACKEND_URL;\nfunction esc(s){ return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); }\nfunction ident(){ var cs="",dev=""; try{ cs=window.PFCallsign?window.PFCallsign():""; }catch(e){} try{ dev=window.PFDeviceId?window.PFDeviceId():""; }catch(e){} return {callsign:cs,device:dev}; }\n/* Friendly copy for read failures (2026-10-03): raw backend strings like\n   \'missing credentials\' are never shown as UI copy. */\nfunction wrErrCopy(e){\n  e=String(e||"");\n  if(e.indexOf("claim unavailable")!==-1||e==="legacy_callsign")\n    return "Could not reach Command. This callsign predates the new auth system and can\'t reconnect on its own — contact MTCSTW to recover it.";\n  if(e==="missing credentials"||e==="unauthorized"||e.indexOf("missing credentials")!==-1)\n    return "Could not reach Command — your callsign needs to reconnect. Re-claim it in Enlistment Ranks (one tap), then retry.";\n  return "Could not reach Command. The wire is down — retry in a bit.";\n}\nfunction api(action,params,cb){\n  if(!BACKEND){ cb(null); return; }\n  /* Private read: warreport_latest is per-callsign (IDOR fix). Route through\n     the shared claim-retry GET (2026-10-03) so pre-auth callsign holders get\n     one auth_claim attempt instead of \'missing credentials\' forever. */\n  if(action==="warreport_latest"){\n    try{\n      if(window.PF && PF.authGetJSONP){ PF.authGetJSONP(BACKEND,action,params,cb); return; }\n      var _sec = (window.PF && PF.getAuthSecret) ? PF.getAuthSecret() : "";\n      if(_sec && params && !params.auth_secret) params.auth_secret=_sec;\n    }catch(e){}\n  }\n  var fn="pfWrCb"+Math.floor(Math.random()*1e9);\n  var s=document.createElement("script"), done=false;\n  function finish(j){ if(done)return; done=true; try{delete window[fn];}catch(e){}\n    if(s.parentNode)s.parentNode.removeChild(s); cb(j); }\n  window[fn]=function(j){ finish(j); };\n  s.onerror=function(){ finish(null); };\n  var q="?action="+encodeURIComponent(action);\n  for(var k in params){ if(params[k]!=null&&params[k]!=="") q+="&"+encodeURIComponent(k)+"="+encodeURIComponent(params[k]); }\n  q+="&callback="+fn; s.src=BACKEND+q; document.head.appendChild(s);\n  setTimeout(function(){ finish(null); },12000);\n}\nfunction paint(el,j){\n  var id=ident();\n  if(!id.callsign){\n    el.innerHTML=\'<div class="c-gate">War Reports are written for enlisted soldiers. Claim your callsign in Enlistment Ranks, then come back for your briefing.</div>\';\n    return;\n  }\n  if(!j||!j.ok){\n    el.innerHTML=\'<div class="c-err">\'+esc(wrErrCopy(j&&j.err))\n      +\'<br><button class="c-btn" id="wrRetry">Retry connection</button></div>\';\n    var rb=document.getElementById("wrRetry"); if(rb) rb.onclick=function(){ load(); };\n    return;\n  }\n  if(!j.report){\n    el.innerHTML=\'<div class="x-pane"><h4>No report yet, soldier</h4>\'\n      +\'<div class="x-note">Command drafts the War Report every Monday. It lands here \'\n      +\'(and in your inbox once email is wired). Check in all week so there is \'\n      + \'something worth writing about.</div></div>\';\n    return;\n  }\n  var r=j.report;\n  var when="";\n  try{ var d=new Date(Number(r.created_at)); if(!isNaN(d.getTime())) when=d.toLocaleDateString(); }catch(e){}\n  el.innerHTML=\'<div class="x-pane"><h4>\'+esc(r.subject||"WAR REPORT")+\'</h4>\'\n    +\'<div class="x-note">Week of \'+esc(r.week_start||"")+(when?" · drafted "+esc(when):"")+\'</div>\'\n    +\'<div class="wr-body" style="white-space:pre-wrap;font-family:monospace;font-size:13px;line-height:1.55;margin-top:8px">\'\n    +esc(r.body||"")+\'</div></div>\';\n}\nfunction load(){\n  var el=document.getElementById("xWarReport"); if(!el) return;\n  var id=ident();\n  if(!id.callsign){ paint(el,{ok:true,report:null}); return; }\n  api("warreport_latest",{callsign:id.callsign},function(j){ paint(el,j); });\n}\nload();\nsetInterval(function(){ try{ if(window.PF&&PF.hidden&&PF.hidden()) return; }catch(e){} load(); },600000);\n})();\n<\/script>\n</div>\n</template>')}(),function(){"use strict";var n=window.PF;n&&!n.skip("climbers-board")&&n.holder().insertAdjacentHTML("beforeend",'<template id="pf-ov-climbers">\n<div class="fe-block pf-override-block" id="pf-climbers">\n<h2>&#128200; Biggest Climbers</h2>\n<div class="c-tag">Not who&#8217;s on top — who&#8217;s moving. XP gained this week. Resets every Monday.</div>\n<div id="xClimbers"><div class="c-load">Reading the ranks&hellip;</div></div>\n</div>\n<script>\n(function(){\nvar BACKEND=window.PF_BACKEND_URL;\nvar GREEN=\'#4caf50\', REDD=\'#e53935\', GOLD=\'#e8b10c\';\nfunction esc(s){ return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); }\nfunction fmt(n){ n=Math.round(Number(n)||0); return n.toString().replace(/\\B(?=(\\d{3})+(?!\\d))/g,","); }\nfunction apiGet(action,params,cb){\n  if(!BACKEND){ cb(null); return; }\n  var fn="pfClimbCb"+Math.floor(Math.random()*1e9);\n  var s=document.createElement("script"), done=false;\n  function finish(j){ if(done)return; done=true; try{delete window[fn];}catch(e){}\n    if(s.parentNode)s.parentNode.removeChild(s); cb(j); }\n  window[fn]=function(j){ finish(j); };\n  s.onerror=function(){ finish(null); };\n  var q="?action="+encodeURIComponent(action);\n  for(var k in params){ if(params[k]!=null&&params[k]!=="") q+="&"+encodeURIComponent(k)+"="+encodeURIComponent(params[k]); }\n  q+="&callback="+fn; s.src=BACKEND+q; document.head.appendChild(s);\n  setTimeout(function(){ finish(null); },12000);\n}\n/* ms until next Monday 00:00 America/Chicago. */\nfunction msToMonday(){\n  try{\n    var now=new Date();\n    var chi=new Date(now.toLocaleString("en-US",{timeZone:"America/Chicago"}));\n    var d=new Date(chi); d.setHours(0,0,0,0);\n    var add=((8-chi.getDay())%7);\n    var next=new Date(d.getTime()+add*86400000);\n    var diff=next.getTime()-chi.getTime();\n    /* Chicago wall-clock vs real elapsed: correct with the true offset. */\n    var offMs=(now.getTime()-new Date(now.toLocaleString("en-US",{timeZone:"America/Chicago"})).getTime());\n    return Math.max(0,diff-offMs);\n  }catch(e){ return 0; }\n}\nfunction fmtLeft(ms){\n  var s=Math.floor(ms/1000), d=Math.floor(s/86400), h=Math.floor(s%86400/3600), m=Math.floor(s%3600/60);\n  if(d>0) return d+"d "+h+"h";\n  if(h>0) return h+"h "+m+"m";\n  return m+"m";\n}\nfunction deltaHTML(d){\n  d=Math.round(Number(d)||0);\n  if(d>0) return \'<span style="color:\'+GREEN+\';font-weight:700;">+\'+fmt(d)+\' &#9650;</span>\';\n  if(d<0) return \'<span style="color:\'+REDD+\';font-weight:700;">\'+fmt(d)+\' &#9660;</span>\';\n  return \'<span style="color:#888;">&mdash;</span>\';\n}\nfunction rowHTML(e,star){\n  var medal=e.rank<=3?[\'&#129351;\',\'&#129352;\',\'&#129353;\'][e.rank-1]:(\'<span style="color:#888;font-weight:700;">\'+e.rank+\'</span>\');\n  return \'<div style="display:flex;align-items:center;gap:10px;padding:9px 4px;border-bottom:1px solid #222;font-family:Arial,sans-serif;">\'\n    +\'<div style="width:34px;text-align:center;font-size:1.1rem;">\'+medal+\'</div>\'\n    +\'<div style="flex:1;min-width:0;"><div style="color:#f5f0e1;font-weight:900;letter-spacing:0.04em;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">\'\n    +esc(String(e.callsign||\'\').toUpperCase())+(star?\' <span style="color:\'+GOLD+\';" title="RISING STAR">&#9733;</span>\':\'\')+\'</div>\'\n    +\'<div style="font-size:0.72rem;color:#888;letter-spacing:0.08em;">THIS WEEK</div></div>\'\n    +\'<div style="text-align:right;"><div style="color:#f5f0e1;font-weight:900;">+\'+fmt(e.gained)+\' <span style="font-size:0.75rem;color:#888;">XP</span></div>\'\n    +\'<div style="font-size:0.78rem;">\'+deltaHTML(e.delta)+\'</div></div>\'\n    +\'</div>\';\n}\nfunction paint(el,j){\n  if(!j||!j.ok){\n    el.innerHTML=\'<div class="c-err">Could not reach Command. The wire is down — retry in a bit.\'\n      +\'<br><button class="c-btn" id="clRetry">Retry</button></div>\';\n    var rb=document.getElementById("clRetry"); if(rb) rb.onclick=function(){ load(); };\n    return;\n  }\n  var h=\'\';\n  if(!j.entries||!j.entries.length){\n    h=\'<div class="x-pane"><h4>No climbers yet this week</h4>\'\n      +\'<div class="x-note">Nobody has earned XP since Monday. Move first — the board is yours to take.</div></div>\';\n  } else {\n    h=j.entries.map(function(e){ return rowHTML(e,false); }).join(\'\');\n    if(j.watch&&j.watch.length){\n      h+=\'<div style="margin:16px 0 4px;color:\'+GOLD+\';font-weight:900;letter-spacing:0.18em;font-size:0.72rem;font-family:Arial,sans-serif;">WITHIN STRIKING DISTANCE</div>\';\n      h+=j.watch.map(function(e){\n        return \'<div style="display:flex;align-items:center;gap:10px;padding:7px 4px;border-bottom:1px dashed #2a2a2a;font-family:Arial,sans-serif;">\'\n          +\'<div style="width:34px;text-align:center;color:#888;font-weight:700;">\'+e.rank+\'</div>\'\n          +\'<div style="flex:1;color:#c9bfa8;font-weight:700;">\'+esc(String(e.callsign||\'\').toUpperCase())+\'</div>\'\n          +\'<div style="text-align:right;font-size:0.82rem;color:#888;">+\'+fmt(e.gained)+\' XP &middot; <span style="color:\'+REDD+\';">\'+fmt(e.gap)+\' behind #10</span></div>\'\n          +\'</div>\';\n      }).join(\'\');\n    }\n  }\n  var left=msToMonday();\n  h+=\'<div class="x-note" style="margin-top:12px;">Top 10 at reset earn the <b style="color:\'+GOLD+\';">RISING STAR</b> badge + 100 XP.\'\n    +(left?\' Resets in <b>\'+esc(fmtLeft(left))+\'</b>.\':\'\')+\'</div>\';\n  el.innerHTML=h;\n}\nfunction load(){\n  var el=document.getElementById("xClimbers"); if(!el) return;\n  apiGet("climber_board",{},function(j){ paint(el,j); });\n}\nload();\nsetInterval(function(){ try{ if(window.PF&&PF.hidden&&PF.hidden()) return; }catch(e){} load(); },300000);\n})();\n<\/script>\n</div>\n</template>')}();
